			reader, err := gzip.NewReader(bytes.NewReader(payload))
			if err != nil {
				return nil, fmt.Errorf("layer %q: opening gzip content: %w", layer.Digest, err)
			}
			payload, readErr = io.ReadAll(reader)
			closeErr = reader.Close()
			if readErr != nil {
				return nil, fmt.Errorf("layer %q: reading gzip content: %w", layer.Digest, readErr)
			}
			if closeErr != nil {
				return nil, closeErr
			}
		}

		files = append(files, &File{
			ReadCloser: io.NopCloser(bytes.NewReader(payload)),
			info: FileInfo{
				desc:      layer,
				encoding:  format,
				namespace: layer.Annotations[AnnotationFliptNamespace],
				mod:       created,
			},
		})
	}

	complete = true
	return files, nil
}

func parseLayerEncoding(encoding string) (format string, compressed bool, err error) {
	format = "json"
	formatSet := false
	for _, part := range strings.Split(encoding, "+") {
		switch part {
		case "json", "yaml", "yml":
			if formatSet {
				return "", false, fmt.Errorf("multiple content formats")
			}
			format = part
			formatSet = true
		case "gzip":
			if compressed {
				return "", false, fmt.Errorf("multiple compression encodings")
			}
			compressed = true
		default:
			return "", false, fmt.Errorf("unsupported encoding")
		}
	}
	return format, compressed, nil
}

func getMediaTypeAndEncoding(layer v1.Descriptor) (mediaType, encoding string, _ error) {
	var ok bool
	if mediaType = layer.MediaType; mediaType == "" {
		return "", "", ErrMissingMediaType
	}

	if mediaType, encoding, ok = strings.Cut(mediaType, "+"); !ok {
		encoding = "json"
	}

	return
}

