type StorageConfig struct {
	Type     StorageType `json:"type,omitempty" mapstructure:"type" yaml:"type,omitempty"`
	Local    *Local      `json:"local,omitempty" mapstructure:"local,omitempty" yaml:"local,omitempty"`
	Git      *Git        `json:"git,omitempty" mapstructure:"git,omitempty" yaml:"git,omitempty"`
	Object   *Object     `json:"object,omitempty" mapstructure:"object,omitempty" yaml:"object,omitempty"`
	OCI      *OCI        `json:"oci,omitempty" mapstructure:"oci,omitempty" yaml:"oci,omitempty"`
	ReadOnly *bool       `json:"read_only,omitempty" mapstructure:"read_only,omitempty" yaml:"read_only,omitempty"`
}

func (c *StorageConfig) setDefaults(v *viper.Viper) error {
	switch v.GetString("storage.type") {
	case string(LocalStorageType):
		v.SetDefault("storage.local.path", ".")
	case string(GitStorageType):
		v.SetDefault("storage.git.ref", "main")
		v.SetDefault("storage.git.poll_interval", "30s")
		if v.GetString("storage.git.authentication.ssh.password") != "" ||
			v.GetString("storage.git.authentication.ssh.private_key_path") != "" ||
			v.GetString("storage.git.authentication.ssh.private_key_bytes") != "" {
			v.SetDefault("storage.git.authentication.ssh.user", "git")
		}
	case string(ObjectStorageType):
		// keep this as a case statement in anticipation of
		// more object types in the future
		// nolint:gocritic
		switch v.GetString("storage.object.type") {
		case string(S3ObjectSubStorageType):
			v.SetDefault("storage.object.s3.poll_interval", "1m")
		}
	case string(OCIStorageType):
		v.SetDefault("store.oci.insecure", false)

		configDir, err := Dir()
		if err != nil {
			return fmt.Errorf("setting oci default: %w", err)
		}

		bundlesDir := filepath.Join(configDir, "bundles")
		if err := os.MkdirAll(bundlesDir, 0755); err != nil {
			return fmt.Errorf("creating image directory: %w", err)
		}

		v.SetDefault("store.oci.bundles_directory", bundlesDir)
	default:

			// we're protecting against this explicitly so we can disable
			// the gosec linting rule
			if auth.SSHAuth.InsecureIgnoreHostKey {
				// nolint:gosec
				method.HostKeyCallback = ssh.InsecureIgnoreHostKey()
			}

			opts = append(opts, git.WithAuth(method))
		}

		source, err := git.NewSource(logger, cfg.Storage.Git.Repository, opts...)
		if err != nil {
			return nil, err
		}

		store, err = fs.NewStore(logger, source)
		if err != nil {
			return nil, err
		}
	case config.LocalStorageType:
		source, err := local.NewSource(logger, cfg.Storage.Local.Path)
		if err != nil {
			return nil, err
		}

		store, err = fs.NewStore(logger, source)
		if err != nil {
			return nil, err
		}
	case config.OCIStorageType:
		ociStore, err := fliptoci.NewStore(cfg.Storage.OCI)
		if err != nil {
			return nil, err
		}
		source, err := fsoci.NewSource(logger, ociStore)
		if err != nil {
			return nil, err
		}
		store, err = fs.NewStore(logger, source)
		if err != nil {
			return nil, err
		}
	case config.ObjectStorageType:
		store, err = NewObjectStore(cfg, logger)
		if err != nil {

	})
	if err != nil {
		return nil, err
	}

	return source, nil
}

// Get builds a new store snapshot based on the configure Git remote and reference.
func (s *Source) Get(ctx context.Context) (_ *storagefs.StoreSnapshot, err error) {
	if err := ctx.Err(); err != nil {
		return nil, err
	}
	var fs fs.FS
	if s.hash != plumbing.ZeroHash {
		fs, err = gitfs.NewFromRepoHash(s.logger, s.repo, s.hash)
	} else {
		fs, err = gitfs.NewFromRepo(s.logger, s.repo, gitfs.WithReference(plumbing.NewRemoteReferenceName("origin", s.ref)))
	}
	if err != nil {
		return nil, err
	}

	return storagefs.SnapshotFromFS(s.logger, fs)
}

// Subscribe feeds gitfs implementations of fs.FS onto the provided channel.
// It blocks until the provided context is cancelled (it will be called in a goroutine).
// It closes the provided channel before it returns.
func (s *Source) Subscribe(ctx context.Context, ch chan<- *storagefs.StoreSnapshot) {
	defer close(ch)

	// NOTE: theres is no point subscribing to updates for a git Hash
	return func(s *Source) {
		s.interval = tick
	}
}

